mapper.select:
SELECT workspace_id,root_path,display_name,trust,revision,updated_at FROM workspaces
WHERE updated_at<#{cursorTime} OR (updated_at=#{cursorTime} AND workspace_id<#{cursorId})
ORDER BY updated_at DESC,workspace_id DESC LIMIT #{limit}

mapper.update:
UPDATE threads SET title=#{title},title_source=#{titleSource},revision=revision+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND deleted_at IS NULL


    AND revision>=#{expectedRevision} AND title_source='PLACEHOLDER'


    AND revision=#{expectedRevision}

UPDATE threads SET provider_id=#{providerId},model_id=#{modelId},reasoning_level=#{reasoningLevel},
  access_mode=#{accessMode},collaboration_mode=#{collaborationMode},revision=revision+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision} AND deleted_at IS NULL

UPDATE threads SET pinned_at=#{pinnedAt},revision=revision+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision}
  AND archived_at IS NULL AND deleted_at IS NULL

UPDATE threads
SET deleted_at=#{occurredAt},pinned_at=NULL,SET archived_at=#{occurredAt},pinned_at=NULL,
  revision=revision+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision} AND deleted_at IS NULL
  AND archived_at IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM thread_lineage
    WHERE child_thread_id=#{threadId} OR parent_thread_id=#{threadId}
  )

UPDATE threads SET archived_at=NULL,pinned_at=NULL,revision=revision+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision}
  AND archived_at IS NOT NULL AND deleted_at IS NULL

mapper.select:
WITH items AS ( SELECT tm.item_id,'message' AS item_kind,tm.created_at,tm.turn_id,NULL AS call_id,NULL AS tool_name, NULL AS tool_ordinal,NULL AS tool_state,tm.message_kind,tm.public_text,m.blocks_json,tm.model_round, NULL AS presentation_json, NULL AS approval_id,NULL AS decision,NULL AS expires_at, CASE WHEN tm.message_kind='USER_INPUT' THEN COALESCE(( SELECT json_group_array(json_object( 'attachmentId',ordered.attachment_id,'displayName',ordered.display_name, 'sizeBytes',ordered.size_bytes,'mediaKind',lower(ordered.media_kind), 'mediaType',ordered.media_type)) FROM (SELECT ma.attachment_id,a.display_name,a.size_bytes,a.media_kind,a.media_type FROM message_attachments ma JOIN attachments a ON a.attachment_id=ma.attachment_id WHERE ma.message_id=tm.item_id ORDER BY ma.ordinal) ordered ),json_array()) ELSE NULL END AS attachments_json, tm.source_thread_id,tm.source_title FROM timeline_messages tm LEFT JOIN messages m ON m.message_id=tm.item_id WHERE tm.thread_id=#{threadId} UNION ALL SELECT call_id||'_call','tool_call',created_at,turn_id,call_id,tool_name,ordinal,state, NULL,NULL,NULL,NULL,presentation_json,NULL,NULL,NULL,NULL,NULL,NULL FROM tools WHERE thread_id=#{threadId} UNION ALL SELECT a.approval_id,'approval',a.requested_at,a.turn_id,a.call_id,t.tool_name,NULL,NULL, NULL,NULL,NULL,NULL,NULL,a.approval_id,a.decision,a.expires_at,NULL,NULL,NULL FROM approvals a JOIN tools t ON t.turn_id=a.turn_id AND t.call_id=a.call_id WHERE a.thread_id=#{threadId} ), ordered_items AS ( SELECT items.*, CASE WHEN message_kind='USER_INPUT' THEN 0 WHEN message_kind='REASONING_SUMMARY' THEN 1 WHEN message_kind='ASSISTANT_PROGRESS' THEN 2 WHEN item_kind='tool_call' THEN 3 WHEN item_kind='approval' THEN 4 ELSE 5 END AS semantic_order, COALESCE(tool_ordinal,-1) AS ordinal_order FROM items ) SELECT * FROM ordered_items
WHERE (created_at,semantic_order,ordinal_order,item_id)>( #{cursorTime}, (SELECT semantic_order FROM ordered_items WHERE item_id=#{cursorId}), (SELECT ordinal_order FROM ordered_items WHERE item_id=#{cursorId}), #{cursorId})
ORDER BY created_at,semantic_order,ordinal_order,item_id LIMIT #{limit}

mapper.insert:
INSERT INTO turn_change_sets(thread_id,turn_id,workspace_id,change_set_json,artifact_id,committed_at)
SELECT #{threadId},#{turnId},#{workspaceId},#{changeSetJson},#{artifactId},#{occurredAt}
WHERE EXISTS(SELECT 1 FROM turns x JOIN threads t ON t.thread_id=x.thread_id
             WHERE x.turn_id=#{turnId} AND x.thread_id=#{threadId} AND t.workspace_id=#{workspaceId}
               AND x.state IN ('COMPLETED','FAILED','CANCELLED'))
